extern void restock(void);
static uint32_t pixels[512*272+64];
static Actor*fresh(void){game_new(73819,0);assert(life_validate(&g));Actor*a=&g.actors[g.selected];a->x=a->y=100;a->autoattack=0;g.money=1000;g.dayTime=12;for(int n=1;n<g.actorCount;n++){g.actors[n].active=0;g.actors[n].target=-1;g.actors[n].attackPhase=0;}for(int k=0;k<POP_GROUPS;k++){WorldEvent*e=&g.population.groups[k];e->x=1250+k%8*15;e->y=1250+k/8*15;g.population.state[k].targetX=e->x;g.population.state[k].targetY=e->y;g.population.state[k].siteX=e->x;g.population.state[k].siteY=e->y;g.life.groups[k].goal=LIFE_SETTLED;for(int i=0;i<e->count;i++){e->reserve[i].x=e->x;e->reserve[i].y=e->y;}}return a;}
static void place(int k,float x,float y){WorldEvent*e=&g.population.groups[k];PopulationState*m=&g.population.state[k];float dx=x-e->x,dy=y-e->y;e->x=x;e->y=y;m->siteX=x;m->siteY=y;m->targetX=x+20;m->targetY=y;for(int i=0;i<e->count;i++){Actor*a=e->spawned?&g.actors[e->members[i]]:&e->reserve[i];a->x+=dx;a->y+=dy;}g.life.groups[k].lastX=x;g.life.groups[k].lastY=y;}
static void group(int k,int type){population_generate(k,type);place(k,380,380);g.population.state[k].seen=1;}
static Actor*unit(int k,int i){WorldEvent*e=&g.population.groups[k];return e->spawned?&g.actors[e->members[i]]:&e->reserve[i];}
static void tick(int n){for(int i=0;i<n;i++)population_tick(1);}
static void shot(const char*name){for(int i=512*272;i<512*272+64;i++)pixels[i]=0xdeadbeef;ui.camX=g.actors[g.selected].x;ui.camY=g.actors[g.selected].y;render_game(pixels,512);for(int i=512*272;i<512*272+64;i++)assert(pixels[i]==0xdeadbeef);char path[120];snprintf(path,sizeof(path),"build/v130/%s.ppm",name);FILE*f=fopen(path,"wb");assert(f);fprintf(f,"P6\n480 272\n255\n");for(int y=0;y<272;y++)for(int x=0;x<480;x++){uint32_t c=pixels[y*512+x];unsigned char rgb[]={c&255,c>>8&255,c>>16&255};fwrite(rgb,1,3,f);}fclose(f);}
static void save(const char*name){char path[100];snprintf(path,sizeof(path),"build/v130/%s.sav",name);assert(life_validate(&g)&&population_validate(&g));assert(save_game(path));}
