 a=fresh();group(0,POP_AMBUSH);a->x=380;a->y=390;tick(1);assert(g.population.groups[0].spawned&&!g.life.groups[0].ambushSprung);int n=g.population.groups[0].members[0];g.actors[n].x=380;g.actors[n].y=380;assert(population_hidden(n));a->y=383;tick(1);assert(g.life.groups[0].ambushSprung==1&&!population_hidden(n));assert(population_tactics(n,.2f));save("ambush");
 a=fresh();group(0,POP_REFUGEES);g.population.groups[0].age=250;tick(1);assert(g.life.groups[0].goal==LIFE_REFUGE&&g.life.groups[0].camp==CAMP_PACKING);int t=g.life.groups[0].targetTown;g.life.groups[0].camp=CAMP_AWAY;place(0,g.population.state[0].targetX,g.population.state[0].targetY);g.population.state[0].targetX=g.population.groups[0].x;tick(1);assert(g.life.groups[0].settled&&unit(0,0)->kind==RECRUIT&&!unit(0,0)->squad&&g.life.towns[t].refugees>0);save("refugees-settled");
 a=fresh();group(0,POP_HUNTERS);group(1,POP_BEASTS);place(1,384,380);a->x=380;a->y=388;assert(population_materialize(0)&&population_materialize(1));for(int i=0;i<g.population.groups[1].count;i++)unit(1,i)->dead=1;g.life.groups[0].goal=LIFE_HUNT;g.life.groups[0].targetGroup=1;g.life.groups[0].targetSerial=g.population.groups[1].serial;for(int i=0;i<600;i++)simulate(.1f);assert(g.life.hunts>0&&g.life.groups[0].goal!=LIFE_HUNT);assert(life_validate(&g));
 puts("PASS: hunters pursue actual packs and transfer finite carcass loot; ambushers hide, trigger and flank; refugees pack, reach safety and become recruitable without joining automatically.");
