 fresh();group(0,POP_ARMY);g.population.groups[0].faction=UNION;for(int t0=0;t0<TOWNS;t0++)if(g.townOwner[t0]==UNION)g.prosperity[t0]=30;tick(1);assert(g.life.groups[0].goal==LIFE_REINFORCE||g.life.groups[0].goal==LIFE_RESUPPLY);
 fresh();group(0,POP_ARMY);z=&g.life.groups[0];m=&g.population.state[0];int target=1;g.population.groups[0].faction=SHOGUN;z->goal=LIFE_RAID;z->targetTown=target;place(0,towns[target].x,towns[target].y);int n=1;Actor*b=&g.actors[n];b->active=1;b->dead=0;b->squad=0;b->kind=GUARD;b->homeTown=target;b->faction=g.townOwner[target];b->unconscious=0;b->health[CHEST]=10;b->x=towns[target].x;b->y=towns[target].y;int money=g.money,kills=g.kills;tick(30);assert(g.townOwner[target]==SHOGUN&&g.money==money&&g.kills==kills);assert(g.life.missions>0);
 fresh();group(0,POP_ARMY);z=&g.life.groups[0];m=&g.population.state[0];g.population.groups[0].faction=UNION;z->goal=LIFE_RESUPPLY;z->targetTown=3;z->sourceTown=0;g.stock[3][RATION]=10;g.stock[0][RATION]=0;place(0,420,420);m->targetX=420;m->targetY=420;tick(1);assert(g.stock[3][RATION]==4&&z->cargo[0]==6&&z->goal==LIFE_DELIVER);save("army-cargo");assert(load_game("build/v130/army-cargo.sav"));z=&g.life.groups[0];m=&g.population.state[0];float px=m->targetX,py=m->targetY;place(0,px,py);m->targetX=px;m->targetY=py;tick(1);assert(g.stock[0][RATION]==6&&!z->cargo[0]&&z->missionDone==1);tick(1);assert(g.stock[0][RATION]==6&&z->missionDone==1);
