static void full_simulation(void){
 game_new(73819,0);Actor*a=&g.actors[g.selected];a->x=a->y=40;int lastMoney=g.money;clock_t start=clock();
 for(int i=0;i<12000;i++){simulate(.1f);if(i%300==0){if(!population_validate(&g)||!life_validate(&g)){printf("FULL INVALID tick %d population %d life %d\n",i,population_validate(&g),life_validate(&g));FILE*f=fopen("build/v130/invalid.bin","wb");fwrite(&g,1,sizeof(g),f);fclose(f);assert(0);}}}
 int alive=0,down=0,starving=0,settled=0;for(int k=0;k<POP_GROUPS;k++){settled+=g.life.groups[k].settled;for(int j=0;j<g.population.groups[k].count;j++){if(g.population.state[k].detached&(1<<j))continue;Actor*b=unit(k,j);alive+=!b->dead;down+=!b->dead&&b->unconscious>0;starving+=!b->dead&&b->hunger<20;}}
 printf("FULL SIM: 20 simulated minutes / 12000 full ticks; alive=%d down=%d hungry=%d settled groups=%d; player money %d->%d, kills=%d; %.2fs host CPU.\n",alive,down,starving,settled,lastMoney,g.money,g.kills,(double)(clock()-start)/CLOCKS_PER_SEC);save("full-simulation");assert(load_game("build/v130/full-simulation.sav"));
}
static void invalid_state(void){fresh();GroupLife*z=&g.life.groups[0];z->carry[0]=1;z->carry[1]=0;assert(!life_validate(&g));z->carry[0]=z->carry[1]=-1;z->goal=LIFE_RESUPPLY;z->targetTown=-1;assert(!life_validate(&g));z->targetTown=0;assert(life_validate(&g));z->clock=NAN;assert(!life_validate(&g));puts("PASS: cyclic carriers, missing mission towns and non-finite timers are rejected.");}
static void endurance(void){
 game_new(73819,0);Actor*a=&g.actors[g.selected];a->x=a->y=40;int invalid=0;clock_t start=clock();
 /* Ten game days in coarse world time, including real town consumption/restocking. */
 for(int sec=0;sec<18000;sec++){population_tick(1);politics_tick(1);society_tick(1);civil_tick(1);g.time++;g.dayTime+=1.f/75;if(g.dayTime>=24){g.dayTime-=24;g.day++;restock();}if(sec%300==0){if(!population_validate(&g)||!life_validate(&g)){printf("INVALID at %d\n",sec);invalid++;break;}}}
 assert(!invalid);printf("ENDURANCE: 10 game days / 5 simulated hours; rescues=%d hunts=%d resupplies=%d relocations=%d refugees=%d missions=%d conflicts=%d; %.2fs host CPU.\n",g.life.rescues,g.life.hunts,g.life.resupplies,g.life.relocations,g.life.settled,g.life.missions,g.population.conflicts,(double)(clock()-start)/CLOCKS_PER_SEC);save("endurance");assert(load_game("build/v130/endurance.sav"));
}
